mapper.select:
SELECT a.`id` AS "id", a.`map_name` AS "mapName", a.`project_id` AS "projectId", a.`map_size` AS "mapSize", a.`scale` AS "scale", a.`file_path` AS "filePath", a.`drawing_pixel_x` AS "drawingPixelX", a.`drawing_pixel_y` AS "drawingPixelY", a.`site_coordinate_x_m` AS "siteCoordinateXM", a.`site_coordinate_y_m` AS "siteCoordinateYM", a.`parent_id` AS "parentId", a.`map_type` AS "mapType", a.`origin_pixel_x` AS "originPixelX", a.`origin_pixel_y` AS "originPixelY", a.`sort_order` AS "sortOrder", a.`status` AS "status", a.`create_by` AS "createBy", a.`create_date` AS "createDate", a.`update_by` AS "updateBy", a.`update_date` AS "updateDate", a.`remarks` AS "remarks" FROM `swm_site_map_management` a WHERE a.`parent_id` = #{parentId}
AND a.`corp_code` = #{corpCode}
ORDER BY a.`sort_order` ASC, a.`create_date` ASC
